#!/bin/sh
# What a module's generated C header includes: exactly what its exported declarations need (knowledge/smith-module-headers.md). Usage: sh tests/headers.sh path/to/smith
#   1. every committed generated header (include/smith/*.h with a `// Generated by smith` line) compiles on its own,
#      as C and as C++;
#   2. the rule, on small modules: an import only a body uses stays out; an import an export's type uses goes in; of two
#      imports the one that declares the name goes in (this needs the compiler inside smith, so a stage0 skips it); an
#      imported module whose type an export uses is included, and one only a body uses is not; an `#include` never goes
#      in; and each of these headers compiles on its own too.
set -u
case $1 in /*) smith=$1 ;; *) smith=$(pwd)/$1 ;; esac
here=$(cd "$(dirname "$0")/.." && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT INT TERM
export XDG_CACHE_HOME=$work/xdg-cache
failures=0
total=0

ok() { # name, status (0: passed)
    total=$((total + 1))
    if [ "$2" -eq 0 ]; then
        echo "ok    $1"
    else
        failures=$((failures + 1))
        echo "FAIL  $1"
    fi
}

standalone() { # name, header, include path
    for mode in "c -std=gnu23" "c++ -std=c++23"; do
        out=$("$smith" cc -fsyntax-only -x $mode -I "$3" "$2" 2>&1)
        status=$?
        ok "$1 compiles alone (${mode%% *})" $status
        [ $status -eq 0 ] || echo "$out" | head -5
    done
}

has() { # name, header, include line (fixed text), wanted: yes or no
    if grep -qxF "$3" "$2"; then found=yes; else found=no; fi
    [ "$found" = "$4" ]
    status=$?
    if [ "$4" = yes ]; then ok "$1: $3 is in the header" $status; else ok "$1: $3 is not in the header" $status; fi
}

# 1. The committed headers.
for header in "$here"/include/smith/*.h; do
    grep -q '^// Generated by smith' "$header" || continue
    standalone "$(basename "$header")" "$header" "$here/include"
done

# 2. The rule.
mkdir -p "$work/src/t" "$work/include/t" "$work/include/u/deep"
cd "$work/src" || exit 1
cat >t/body.smith <<'S'
module t::body;
import <stdio.h>;
export u32 body_only(u32 x) {
    c::printf("%u\n", x);
    return x;
}
S
cat >t/typed.smith <<'S'
module t::typed;
import <stdio.h>;
export c::FILE *typed_open(const char *path);
S
cat >t/two.smith <<'S'
module t::two;
import <string.h>;
import <stdio.h>;
export c::FILE *two_stream(void);
export u32 two_length(const char *s) {
    return (u32)c::strlen(s);
}
S
cat >t/tag.smith <<'S'
module t::tag;
import <sys/stat.h>;
import <stdio.h>;
export u32 tag_size(struct c::stat *info);
S
cat >t/include.smith <<'S'
module t::include;
#include <stdio.h>
#include <string.h>
export u32 include_only(u32 x) {
    puts("x");
    return x + (u32)strlen("y");
}
S
cat >t/point.smith <<'S'
module t::point;
export typedef struct {
    i32 x;
    i32 y;
} Point;
export Point origin(void) {
    return (Point){0, 0};
}
S
cat >t/uses.smith <<'S'
module t::uses;
import t::point;
export point::Point shifted(point::Point p);
S
cat >t/body_module.smith <<'S'
module t::body_module;
import t::point;
export i32 body_module_x(void) {
    return point::origin().x;
}
S
mkdir -p u/deep
cat >u/far.smith <<'S'
module u::far;
import t::point;
export typedef struct {
    point::Point at;
} Far;
S
cat >u/deep/farther.smith <<'S'
module u::deep::farther;
import t::point;
import u::far;
export far::Far farther(far::Far f, point::Point p);
S
for module in body typed two tag include point uses body_module; do
    "$smith" cc --smith-header "t/$module.smith" -o "$work/include/t/$module.h" 2>"$work/err.$module"
    ok "$module: the header is written" $?
done
"$smith" cc --smith-header u/far.smith -o "$work/include/u/far.h" 2>"$work/err.far"
ok "far: the header is written" $?
"$smith" cc --smith-header u/deep/farther.smith -o "$work/include/u/deep/farther.h" 2>"$work/err.farther"
ok "farther: the header is written" $?

has "body: an import only a body uses" "$work/include/t/body.h" "#include <stdio.h>" no
has "typed: an import an export's type uses" "$work/include/t/typed.h" "#include <stdio.h>" yes
has "include: an #include" "$work/include/t/include.h" "#include <stdio.h>" no
has "include: an #include" "$work/include/t/include.h" "#include <string.h>" no
# A module is included relative to the header that includes it, so the headers of one tree find each other with no
# include path of their own (a stage0 compiling smith.c has none).
has "uses: an imported module an export's type uses" "$work/include/t/uses.h" '#include "point.h"' yes
has "body_module: an imported module only a body uses" "$work/include/t/body_module.h" '#include "point.h"' no
has "far: a module in another folder" "$work/include/u/far.h" '#include "../t/point.h"' yes
has "farther: a module in a folder above" "$work/include/u/deep/farther.h" '#include "../../t/point.h"' yes
has "farther: a module beside the folder" "$work/include/u/deep/farther.h" '#include "../far.h"' yes
has "every header: the sized types' headers" "$work/include/t/body.h" "#include <stdint.h>" yes

if "$smith" cc --smith-which -x c 2>/dev/null | grep -q "token-hook yes"; then
    has "two: the import that declares the name" "$work/include/t/two.h" "#include <stdio.h>" yes
    has "two: the one that does not" "$work/include/t/two.h" "#include <string.h>" no
    has "tag: the import that declares the tag" "$work/include/t/tag.h" "#include <sys/stat.h>" yes
    has "tag: the one that does not" "$work/include/t/tag.h" "#include <stdio.h>" no
else
    echo "skip  two, tag: this smith has no clang with the token hook inside to ask"
fi

for module in body typed two tag include point uses body_module; do
    standalone "t/$module.h" "$work/include/t/$module.h" "$work/include"
done
standalone "u/far.h" "$work/include/u/far.h" "$work/include"
standalone "u/deep/farther.h" "$work/include/u/deep/farther.h" "$work/include"
# and with no include path at all: the header finds the headers it includes beside itself
for mode in "c -std=gnu23" "c++ -std=c++23"; do
    "$smith" cc -fsyntax-only -x $mode "$work/include/u/deep/farther.h" 2>/dev/null
    ok "u/deep/farther.h compiles with no include path (${mode%% *})" $?
done

# A generic called with its type written in a body needs no instance in a header: it stays a plain call
cat >t/typed_call.smith <<'S'
module t::typed_call;
import smith::test;
export void typed_call_test(void) {
    test::check_equal(1, 1);
}
S
"$smith" cc --smith-header t/typed_call.smith -o "$work/include/t/typed_call.h" -I "$here/include" 2>"$work/err.typed_call"
ok "typed_call: a generic with its type written in a body does not stop the header" $?
cat "$work/err.typed_call" | head -5

# A module's imports are read, and theirs: a chain longer than the old limit of eight modules, by source and by header
mkdir -p chain
i=0
while [ $i -lt 20 ]; do
    {
        echo "module chain::m$i;"
        [ $i -lt 19 ] && echo "import chain::m$((i + 1));"
        if [ $i -lt 19 ]; then echo "export u32 m$i(void) { return m$((i + 1))::m$((i + 1))() + 1; }"; else echo "export u32 m$i(void) { return 1; }"; fi
    } >chain/m$i.smith
    i=$((i + 1))
done
"$smith" cc --smith-header chain/m0.smith -o "$work/chain-source.h" 2>"$work/err.chain"
ok "chain: twenty modules read by source" $?
head -3 "$work/err.chain"
mkdir -p "$work/include/chain"
i=19
while [ $i -ge 1 ]; do
    "$smith" cc --smith-header chain/m$i.smith -o "$work/include/chain/m$i.h" -I "$work/include" 2>>"$work/err.chain"
    i=$((i - 1))
done
"$smith" cc --smith-header chain/m0.smith -o "$work/chain-headers.h" -I "$work/include" 2>>"$work/err.chain"
ok "chain: twenty modules read by header" $?
cat >chain/last.smith <<'S'
module chain::last;
import chain::m0;
import t::point;
export point::Point last(void) {
    return point::origin();
}
S
"$smith" cc --smith-header chain/last.smith -o "$work/chain-last.h" -I "$work/include" 2>"$work/err.last"
ok "chain: an import after twenty others is still found" $?
head -3 "$work/err.last"
mkdir -p deep
i=0
while [ $i -lt 140 ]; do
    {
        echo "module deep::m$i;"
        [ $i -lt 139 ] && echo "import deep::m$((i + 1));"
        echo "export u32 m$i(void);"
    } >deep/m$i.smith
    i=$((i + 1))
done
"$smith" cc --smith-header deep/m0.smith -o "$work/deep.h" 2>"$work/err.deep"
status=$?
[ $status -ne 0 ] && grep -q "smith_raw_modules_max" "$work/err.deep"
ok "deep: more modules than the limit is an error that names it" $?

echo
echo "$total header checks, $failures failed"
[ "$failures" -eq 0 ]
